/* A dimension walkthrough, not an inference engine; values follow the bundled P5 YOLOv5l. */
(() => {
  const lesson=lessons.find(x=>x.id==='architecture'); if(!lesson)return;
  const photo='assets/image-flow/bus.jpg';
  const entries=[
    [-1,'Conv',64,2,1],[-1,'Conv',128,4,1],[-1,'C3',128,4,3],[-1,'Conv',256,8,1],[-1,'C3',256,8,6],[-1,'Conv',512,16,1],[-1,'C3',512,16,9],[-1,'Conv',1024,32,1],[-1,'C3',1024,32,3],[-1,'SPPF',1024,32,1],[-1,'Conv',512,32,1],[-1,'Upsample',512,16,1],[[11,6],'Concat',1024,16,1],[-1,'C3',512,16,3],[-1,'Conv',256,16,1],[-1,'Upsample',256,8,1],[[15,4],'Concat',512,8,1],[-1,'C3',256,8,3],[-1,'Conv',256,16,1],[[18,14],'Concat',512,16,1],[-1,'C3',512,16,3],[-1,'Conv',512,32,1],[[21,10],'Concat',1024,32,1],[-1,'C3',1024,32,3],[[17,20,23],'Detect',null,null,1]
  ].map((r,i)=>({i,from:r[0],type:r[1],c:r[2],s:r[3],n:r[4]}));
  const sources=r=>Array.isArray(r.from)?r.from:[r.i-1];
  const fmt=n=>n.toLocaleString('en-US');
  const quiz=(q,options,answer,why)=>({q,options,answer,why});
  const sections=[
    {title:'13. 实图案例：810×1080照片怎样成为输入张量',paragraphs:[
      '下面使用YOLOv5官方仓库的bus.jpg，实际文件宽810、高1080，RGB三通道。图片通常写“宽×高”，数组与张量却按高、宽排列：OpenCV读入时为[1080,810,3]、uint8、BGR顺序。请始终分清W×H和H×W。本案例沿用本课YOLOv5l、nc=80与3组anchor/尺度，不加载权重，也不声称生成了真实预测。',
      '先走固定640×640的letterbox：缩放比r=min(640/1080,640/810)=16/27≈0.592593。图像内容缩成宽480、高640，为保持比例不拉伸，需要左右各填充80像素，填充值114。结果数组为[640,640,3]，其中左右灰边不是原图内容。这里明确设置auto=False；训练默认方形批次可以用它作为尺寸推导基线。',
      '随后BGR→RGB，HWC→CHW，整理连续内存，得到[3,640,640]。加入批次维得到[1,3,640,640]，转浮点并除以255使像素落在[0,1]。通道换序不改变空间尺寸，除以255不改变张量形状。输入采用float32时仅该张量占4.69 MiB；这不是运行整个模型所需的显存。',
      '推理常见的auto=True会把多余填充量对32取余。本照片的总横向填充160，160 mod 32=0，因此可以不填灰边，实际输入为[1,3,640,480]，并不是640×640。不是所有图片都会变成这个矩形，批处理、后端与rect设置也会影响最终输入。为方便对照，下方的选择会同步改变后续案例图表；训练步骤演示固定采用方形基线。',
      '绿色框是为坐标换算手工设置的教学框，近似圈住左侧行人：原图xyxy=(54,405,243,918)，不属于官方标注，也不是模型预测。方形输入后变为(112,240,224,544)；中心xywh=(168,392,112,304)。真实训练必须完整标注需要学习的所有目标，不能把这张示意框当作整张照片的完整训练标签。'
    ],exercise:quiz('这张照片用auto=True、stride=32做最小矩形letterbox，输入高宽是多少？',['640×640','640×480','480×640'],1,'原图宽810、高1080，缩到宽480、高640；横向多余160对32取余为0，最终H×W=640×480。')},
    {title:'14. 实图逐层流动：0～24层与模块内部尺寸',paragraphs:[
      '下面把同一张照片送入网络，完整列出每一层的来源、输入与输出。所有普通特征按[B,C,H,W]显示；Detect原始预测改用[B,anchor,H,W,85]。切换批次大小只改变B，切换填充方式才会改变空间尺寸。B=4表示案例照片加上3张同样预处理尺寸的其他照片，不是把一个图像的通道复制4遍。',
      '默认方形输入依次经过640→320→160→80→40→20。第0层6×6、s=2、p=2：floor((640+4−6)/2)+1=320；第1层3×3、s=2、p=1得到160。其余步长2层同理。矩形输入则是H:640→320→160→80→40→20，W:480→240→120→60→30→15。C/H/W都是张量轴，不是类别数量。',
      '每个节点的输出通常是学习到的特征，不再是可以当普通照片直接展示的RGB图像。后面图表中的高宽数字表达空间分辨率，不代表真实激活热图。网络的权重和输入值决定特征数值；本案例只依据源码推导尺寸与连接，不伪造中间层实际输出。',
      '网络不是一条只保留上一层的流水线。层4、6的输出要留给FPN横向融合；层10、14的输出要留给PAN融合；层17、20、23同时送给Detect。点击节点后，图中会标出它读取的来源。Concat保留两路通道，例如层12把512与512拼为1024，随后层13的C3再融合为512。',
      '选中C3、SPPF或Detect，可以继续查看内部形状。C3的两路分支读取同一个输入；Bottleneck的Add只在shortcut开启且形状匹配时发生。SPPF的池化链保持高宽，四份512通道拼为2048通道。Detect三个输出卷积保持各自网格高宽，把通道变为255，然后分组和换轴。'
    ],exercise:quiz('矩形输入[1,3,640,480]，层17的P3特征是什么形状？',['[1,256,80,60]','[1,255,80,80]','[1,3,80,60,85]'],0,'层17是Neck的C3输出，通道256、stride=8。Detect尚未执行，所以不是255通道或5维预测。')},
    {title:'15. 训练全程：照片、标签、损失和参数更新',paragraphs:[
      '先固定训练基线：B=1、640×640、nc=80，关闭Mosaic、MixUp、随机透视/翻转、额外复制粘贴与multi-scale，采用非rect方形批次，才能逐项核对这里的坐标。项目的数据加载器还包含自定义增强；开启任何几何增强都必须同步变换标签，这时不能继续套用本案例的固定框坐标。',
      'YOLO标签文件每行是[class,xc/W,yc/H,w/W,h/H]。教学框假定类别person=0，原图对应[0,0.183333,0.6125,0.233333,0.475]。经过方形letterbox后，归一化标签变为[0,0.2625,0.6125,0.175,0.475]。DataLoader合批后额外增加image_index，targets为[N,6]；本框在批次第0张中可写[0,0,0.2625,0.6125,0.175,0.475]。N是批次内全部标注框数，与批次大小B不同。',
      'model.train()前向输出三个raw张量：[B,3,80,80,85]、[B,3,40,40,85]、[B,3,20,20,85]。训练不会先对它们做NMS再求损失，也没有要求网络产生与标注数量相同的候选。build_targets依据框宽高与anchor的比例筛选匹配，并可能扩展到邻近网格：一个真值可以对应多个尺度、anchor与位置，不能简单说“一个物体只归一个格子”。',
      '本框在P3网格的中心为(168/8,392/8)=(21,49)，宽高为(14,38)个网格单位。这只是坐标换算，是否匹配某个anchor以及会分配哪些邻格，还要按build_targets规则判定。损失挑选正样本框并解码，计算CIoU相关定位项；物体性在全部位置计算，匹配位置的目标可由IoU构造；类别项通常对正样本计算，nc=1时此实现跳过类别项。',
      '加权损失是一个可反向传播的标量，loss.backward()沿计算图计算参数梯度；optimizer.step()根据梯度和优化器状态更新权重，随后清理梯度进入下一轮。更新的是卷积等层的参数，图片不是被“改写成答案”。梯度张量的形状与对应参数一致，例如P3输出卷积权重和梯度都是[255,256,1,1]。',
      '教学循环展示每批更新一次；实际train.py还使用AMP梯度缩放、梯度累积、梯度裁剪与EMA。梯度累积时，并非每个batch都立刻step。训练模式中的BN更新运行统计量，评估模式改用已有统计量；model.eval()本身不会关闭自动求导，还应在推理中使用no_grad或inference_mode。验证在独立数据上评估并选择权重，不能用训练损失直接替代检测质量。'
    ],code:'# 方形输入、关闭几何增强后的单批次教学循环\nmodel.train()\noptimizer.zero_grad()\nimages = images.to(device).float() / 255.0  # [B,3,640,640]\nraw = model(images)                       # 三个5维预测张量\nloss, loss_items = compute_loss(raw, targets.to(device))\nloss.backward()                          # 梯度流向可学习参数\noptimizer.step()                         # 教学简化：每批更新\n# 正式train.py另含AMP、梯度累积、裁剪与EMA等',exercise:quiz('训练标签targets的第一维N表示什么？',['batch中的图片数','batch中的标注框总数','Detect候选总数'],1,'合批标签[N,6]的每一行是一条标注，包含image_index与class以及4个归一化框参数。')},
    {title:'16. 推理全程：候选解码、NMS与原图坐标还原',paragraphs:[
      '推理先加载训练后的权重，设置model.eval()，再在torch.inference_mode()中前向计算。不需要真实标签，也不执行loss.backward或optimizer.step。主干和Neck仍进行同样的特征计算；输入高宽不同则中间形状随之改变，训练所得卷积权重仍可用于这些合法的空间尺寸。',
      '方形输入的三尺度原始预测展平后为[B,19200,85]、[B,4800,85]、[B,1200,85]，合为[B,25200,85]。矩形输入则为[B,14400,85]、[B,3600,85]、[B,900,85]，合为[B,18900,85]。每张图分别处理，B=4不会把4张图的候选混在一起做NMS。',
      'Detect把tx/ty/tw/th经过Sigmoid并结合网格、stride与anchor解码为输入画布中的中心xywh。物体性与类别独立Sigmoid，再由外部后处理相乘得到类别置信度。80类分数不要求总和为1；分数也不自动具有已校准真实概率的含义。',
      '为专注坐标还原，假设有一个候选恰好等于教学框：方形输入xywh=(168,392,112,304)。转成xyxy=(112,240,224,544)。这是假设数值，不是实际模型输出。若该候选物体性0.9、person分数0.8，组合置信度为0.72；它是否最终保留还取决于阈值、重叠框、类别和NMS规则。',
      'NMS之后每张图是[Mi,6]，每行通常为[x1,y1,x2,y2,confidence,class]，Mi随图片变化，可能为0。框还在输入画布中，应先去掉填充，再除以r：原图x=(输入x−pad_x)/r，原图y=(输入y−pad_y)/r，最后裁到图像范围。代入本框即可还原(54,405,243,918)，再叠加到原图上；普通detect.py还会取整。',
      '完整路径因此是：读图→保持比例缩放/填充→RGB/CHW/浮点/合批→Backbone→FPN/PAN→Detect→解码与候选拼接→分数筛选/NMS→坐标还原→显示结果。图片尺寸和预处理参数是这条链的一部分，不能只看模型最后的25200这个数字。'
    ],code:'model.eval()\nwith torch.inference_mode():\n    decoded, raw = model(images)\n# decoded: [B,25200,85]（640×640）\n#       或 [B,18900,85]（640×480）\ndetections = non_max_suppression(decoded, conf_thres=0.25, iou_thres=0.45)\nfor image_id, det in enumerate(detections):\n    # det: [Mi,6]；空结果为[0,6]\n    det[:, :4] = scale_boxes(images.shape[2:], det[:, :4], originals[image_id].shape)\n# 预处理元数据必须与当前图片一一对应',exercise:quiz('方形letterbox中输入坐标x=112，pad_x=80、r=16/27，对应原图x是多少？',['189','54','32'],1,'先减去80像素填充，再除以16/27：(112−80)×27/16=54。')}
  ];
  lesson.sections.push(...sections);
  lesson.sections[0].paragraphs.push('想把网络结构与一张具体照片连起来，请接着阅读第13～16节实图案例：从原始810×1080照片、预处理和各层张量，一直追踪到训练更新与推理坐标还原。');
  lesson.time=155;
  lesson.goals.push('用810×1080实图核算方形/矩形输入、逐层张量、训练标签和原图坐标还原。');
  lesson.keypoints.push('原图宽810高1080：方形letterbox为640×640，auto最小矩形可为640×480；对应候选数25200与18900。');
  lesson.chapterExercises.push(sections[1].exercise,sections[3].exercise);
  lesson.chapterExercises.push(quiz('在本框、固定anchor、anchor_t=4的算例中，为什么共10条正样本分配？',['P3/P4/P5各分配一个，总数再乘3','P4一组anchor对应1格；P5三组anchor各对应3格','每个物体固定分配10格'],1,'本例P3未通过比例匹配；P4为1×1，P5为3×3，共10条。其它框、阈值或anchor可产生不同数量。'),quiz('仅提高NMS的IoU阈值，抑制会怎样变化？',['更宽松，可能留下更多重叠框','更严格，一定只剩一个框','会让模型重新计算卷积特征'],0,'只有IoU大于阈值的框才被抑制；提高阈值会放宽这一抑制条件，不会重新训练或运行卷积。'));
  lesson.sources.push({label:'随课实图来源：YOLOv5官方bus.jpg',url:'https://github.com/ultralytics/yolov5/blob/master/data/images/bus.jpg'});
  let choice={rect:false,b:1};
  const width=()=>choice.rect?480:640;
  const shape=i=>i<0?`[${choice.b},3,640,${width()}]`:`[${choice.b},${entries[i].c},${640/entries[i].s},${width()/entries[i].s}]`;
  const raw=s=>`[${choice.b},3,${640/s},${width()/s},85]`;
  const settings=()=>`<div class="if-settings"><label>输入画布<select data-if-layout aria-label="实图输入画布"><option value="square"${!choice.rect?' selected':''}>固定方形640×640 · auto=False</option><option value="rect"${choice.rect?' selected':''}>推理最小矩形640×480 · auto=True</option></select></label><label>批次B<select data-if-batch aria-label="实图批次大小"><option${choice.b===1?' selected':''}>1</option><option${choice.b===4?' selected':''}>4</option></select></label></div>`;
  function imageCanvas(original=false){const w=original?810:width(),h=original?1080:640,x=original?0:choice.rect?0:80,iw=original?810:480,box=original?[54,405,189,513]:[choice.rect?32:112,240,112,304];return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${original?'原始810乘1080照片与教学框':'letterbox输入画布与教学框'}"><rect width="${w}" height="${h}" fill="#727272"/><image href="${photo}" x="${x}" y="0" width="${iw}" height="${h}"/><rect x="${box[0]}" y="${box[1]}" width="${box[2]}" height="${box[3]}" fill="#49e9a6" fill-opacity=".12" stroke="#30f09e" stroke-width="${original?5:3}"/></svg>`;}
  function preprocess(){const pad=choice.rect?0:80;return `<div class="if-photo-pair"><figure>${imageCanvas(true)}<figcaption>原始文件：W=810、H=1080<br>数组 [1080,810,3] · uint8</figcaption></figure><span class="if-arrow" aria-hidden="true">→</span><figure>${imageCanvas()}<figcaption>网络画布：W=${width()}、H=640<br>r=16/27；左右填充各${pad}px</figcaption></figure></div><div class="if-flowline"><span>HWC / BGR<br>[640,${width()},3]</span><b>→</b><span>RGB / CHW<br>[3,640,${width()}]</span><b>→</b><span>合批 / float32 / ÷255<br>${shape(-1)}</span></div><p class="if-note">绿色框是手工设定的坐标教学框。第一张图在批次中索引为0。输入张量float32占用 ${(choice.b*3*640*width()*4/1048576).toFixed(2)} MiB，不包含权重、特征缓存与梯度。</p><div class="if-math">xyxy：原图 (54,405,243,918) → 画布 (${32+pad},240,${144+pad},544)<br>画布中心xywh：(${88+pad},392,112,304)<br>合批标签示例：[0,0,${((88+pad)/width()).toFixed(6)},0.612500,${(112/width()).toFixed(6)},0.475000]</div>`;}
  function layers(root){const id=Number(root.dataset.layer||0),r=entries[id],ins=sources(r),active=new Set(ins);const groups=[[0,9,'Backbone · 提取'],[10,17,'FPN · 向细尺度融合'],[18,24,'PAN与Detect · 聚合和预测']];return `<div class="if-layer-map">${groups.map(([a,b,label])=>`<div><h4>${label}</h4>${entries.slice(a,b+1).map(n=>`<button type="button" data-if-layer="${n.i}" aria-pressed="${id===n.i}" class="${active.has(n.i)?'if-source':''}"><b>${n.i}</b> ${n.type}<small>${n.i===24?'读取17、20、23':shape(n.i)}</small></button>`).join('')}</div>`).join('')}</div><p class="if-note">紫色为当前层，绿色边框为它读取的来源。节点按功能分组，具体连接以来源标注为准；检测层同时读取三条尺度。</p><div class="if-layer-detail" aria-live="polite"><span class="if-kicker">层 ${id} · ${r.type}</span><div class="if-flowline">${ins.map(i=>`<span>${i<0?'网络输入':'层'+i}<br>${shape(i)}</span>`).join('<b>＋</b>')}<b>→</b><span>层${id}输出<br>${id===24?[8,16,32].map(raw).join('<br>'):shape(id)}</span></div><p>${inner(r)}</p></div><details class="if-all-shapes"><summary>展开全部0～24层输入／输出尺寸表</summary><div class="if-table-scroll" tabindex="0" aria-label="逐层张量尺寸表"><table><thead><tr><th>层 / 模块</th><th>来源</th><th>输入 [B,C,H,W]</th><th>输出张量</th></tr></thead><tbody>${entries.map(n=>`<tr><td>${n.i} ${n.type}</td><td>${sources(n).join(', ')}</td><td>${sources(n).map(shape).join('<br>')}</td><td>${n.i===24?[8,16,32].map(raw).join('<br>'):shape(n.i)}</td></tr>`).join('')}</tbody></table></div></details>`;}
  function inner(r){const h=640/r.s,w=width()/r.s,input=entries[r.i-1]?.c||3;
    if(r.type==='C3'){const hidden=r.c/2,add=r.i<10;return `内部拆解：两路同时读入${input}通道。主路1×1 Conv → [${choice.b},${hidden},${h},${w}] → ${r.n}个Bottleneck；旁路1×1 Conv → 同形状。每个Bottleneck内部1×1与3×3均保持${hidden}通道和${h}×${w}网格${add?'，再执行x+F(x)残差相加':'；shortcut=False，不做残差相加'}。两路Concat → [${choice.b},${2*hidden},${h},${w}] → cv3融合为${shape(r.i)}。`;}
    if(r.type==='SPPF')return `内部拆解：cv1将1024→512通道，得到[${choice.b},512,${h},${w}]。三次5×5最大池化均s=1、p=2，各自保持此形状；原分支加三份池化结果Concat为[${choice.b},2048,${h},${w}]，cv2融合为${shape(r.i)}。没有残差相加。`;
    if(r.type==='Detect')return `内部拆解：层17/20/23分别经1×1卷积，输出${[8,16,32].map(s=>`[${choice.b},255,${640/s},${width()/s}]`).join('、')}。各自view成[B,3,85,H,W]，再permute成[B,3,H,W,85]。三尺度每张图共${fmt(3*(640/8*width()/8+640/16*width()/16+640/32*width()/32))}个候选。训练返回raw列表；推理继续解码。更细的通道含义见第10节。`;
    if(r.type==='Concat')return `沿通道轴dim=1拼接：${sources(r).map(i=>entries[i].c).join('+')}=${r.c}。高宽必须相同；这不是逐元素残差相加。拼接本身没有可学习参数。`;
    if(r.type==='Upsample')return `nearest上采样×2：复制特征值，将高宽翻倍为${h}×${w}，${r.c}通道保持不变。此操作没有可学习参数。`;
    return `${r.i===0?'6×6卷积，s=2、p=2':r.s===entries[r.i-1]?.s?'1×1卷积，s=1':'3×3卷积，s=2、p=1'}：${input}→${r.c}通道；随后BN与SiLU保持形状${shape(r.i)}。卷积改变的是特征表示，不是把原图直接裁成这些小图片。`;
  }
  const trainSteps=[
    ['① 图像与标签','输入[1,3,640,640]；教学框标签[0,0,0.2625,0.6125,0.175,0.475]。标签不是拼成第4个图像通道，而是作为另一份数据交给损失函数。'],
    ['② 前向预测','经过0～23层，再由Detect返回[1,3,80,80,85]、[1,3,40,40,85]、[1,3,20,20,85]。此时还没有NMS，也没有最终物体列表。'],
    ['③ 匹配与损失','build_targets比较真值宽高与anchor比例，并处理邻格。正样本定位损失+全网格物体性损失+正样本类别损失，经权重组合成标量。标签数量不必等于候选数量。'],
    ['④ 反向传播','loss.backward()按计算图求梯度。P3输出卷积weight.grad为[255,256,1,1]，bias.grad为[255]；前面的可学习层也收到梯度。反向传播不是PAN的自底向上前向路径。'],
    ['⑤ 参数更新','optimizer.step()更新权重，清理梯度后继续下一批。真实训练可累积多个batch再更新，并使用AMP与EMA等；这里一次更新是教学简化。']
  ];
  function training(root){const step=Number(root.dataset.step||0);return `<div class="if-train-flow" role="group" aria-label="训练过程步骤">${trainSteps.map((s,i)=>`<button type="button" data-if-train-step="${i}" aria-pressed="${step===i}">${s[0]}</button>`).join('<b aria-hidden="true">→</b>')}</div><div class="if-layer-detail" aria-live="polite"><h4>${trainSteps[step][0]}</h4><p>${trainSteps[step][1]}</p></div><div class="if-cycle"><span>照片 → 预测 → 损失</span><strong>← 梯度沿计算图返回可学习参数</strong><span>更新权重 → 下一批照片 → 下一轮前向</span></div><p class="if-note">本训练演示固定B=1、方形640×640。图示只展示计算关系，未实际执行训练。前面逐层表可以另选B=4查看批次轴如何变化。</p>`;}
  function inference(root){const s=Number(root.dataset.step||0),pad=choice.rect?0:80,candidates=choice.rect?18900:25200,stages=[
    ['① 读取与预处理',`原图[1080,810,3] → 输入${shape(-1)}。记录r=16/27、pad_x=${pad}、pad_y=0，供最后坐标还原。`],
    ['② 特征与原始预测',`三尺度网格80×${width()/8}、40×${width()/16}、20×${width()/32}；raw形状分别为${[8,16,32].map(raw).join('、')}。`],
    ['③ 解码与拼接',`每个候选变成输入画布中的xywh、物体性与类别分数，三尺度拼接[${choice.b},${candidates},85]。教学假设框xywh=(${88+pad},392,112,304)，不是实际预测。`],
    ['④ 筛选与NMS',`假设物体性0.9、person分数0.8，则组合分数0.72。分别对每张图筛选/NMS，得到长度为B的列表，每项[Mi,6]；Mi可为0。`],
    ['⑤ 还原到原图',`假设教学框保留：输入xyxy=(${32+pad},240,${144+pad},544)。先减(${pad},0)，再除以16/27 → 原图(54,405,243,918)，裁到810×1080范围后显示。`]
  ];return `<div class="if-train-flow" role="group" aria-label="推理过程步骤">${stages.map((a,i)=>`<button type="button" data-if-infer-step="${i}" aria-pressed="${s===i}">${a[0]}</button>`).join('<b aria-hidden="true">→</b>')}</div><div class="if-layer-detail" aria-live="polite"><h4>${stages[s][0]}</h4><p>${stages[s][1]}</p></div><div class="if-photo-pair"><figure>${imageCanvas()}<figcaption>输入画布上的教学候选框</figcaption></figure><span class="if-arrow" aria-hidden="true">→</span><figure>${imageCanvas(true)}<figcaption>去填充、除缩放比，回到原图</figcaption></figure></div><p class="if-note">图片是真实照片；绿色框和0.72分数用于手算，均不是运行模型得到的检测结果。</p>`;}
  const detailTable=(head,rows)=>`<div class="if-table-scroll" tabindex="0" aria-label="计算明细表"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const detailBlock=(title,text)=>`<div class="if-detail-block"><h4>${title}</h4>${text}</div>`;
  function moduleGraphic(r){
    const h=640/r.s,w=width()/r.s,b=choice.b,hw=`${h}×${w}`,input=entries[r.i-1]?.c||3;
    if(r.type==='C3')return `<div class="if-module-inside"><h4>把层${r.i}的C3展开</h4><div class="if-math">共同输入：[${b},${input},${h},${w}]</div><div class="if-branches"><div><strong>主路 cv1：${input}→${r.c/2}</strong>${Array.from({length:r.n},(_,i)=>`<span>Bottleneck ${i+1}<br>1×1 Conv → 3×3 Conv<br>${r.c/2}通道，${hw}<br>${r.i<10?'↶ x + F(x) · 残差Add':'shortcut=False'}</span>`).join('')}</div><div><strong>旁路 cv2：${input}→${r.c/2}</strong><span>保留这一份变换后的特征<br>[${b},${r.c/2},${h},${w}]<br>等主路走完，再一起拼接</span></div></div><div class="if-math">两路Concat：[${b},${r.c},${h},${w}]<br>cv3（1×1 Conv）：${r.c}→${r.c} → 输出${shape(r.i)}</div><p class="if-note">每个Conv块内部都是Conv2d→BN→SiLU；Bottleneck相加后没有再额外加一个激活层。主路中的每个Bottleneck都保留同一张量形状。</p></div>`;
    if(r.type==='SPPF')return `<div class="if-module-inside"><h4>SPPF四份特征如何收集</h4><div class="if-flowline"><span>x0：cv1后<br>[${b},512,${h},${w}]</span><b>→</b><span>y1：MaxPool 5×5<br>形状不变</span><b>→</b><span>y2：再MaxPool<br>形状不变</span><b>→</b><span>y3：再MaxPool<br>形状不变</span></div><div class="if-math">收集[x0,y1,y2,y3] → Concat：[${b},2048,${h},${w}]<br>cv2（1×1 Conv）2048→1024 → ${shape(r.i)}</div><p class="if-note">三次池化串联计算，四路结果一起拼接；不是把同一张特征图重复拼四次。</p></div>`;
    if(r.type==='Detect')return `<div class="if-module-inside"><h4>三个尺度各有一条输出通路</h4>${[17,20,23].map((i,j)=>`<div class="if-flowline"><span>层${i}<br>${shape(i)}</span><b>→</b><span>1×1 Conv2d<br>${entries[i].c}→255 · 含bias</span><b>→</b><span>view + permute<br>${raw([8,16,32][j])}</span></div>`).join('')}<p class="if-note">这三条输出通路没有BN/SiLU。图中三个Conv各自联合产生框、物体性和类别数值。</p></div>`;
    return '';
  }
  function preDetail(){return detailBlock('13.1 先把“像素值”和“张量位置”分清',`<p>用Pillow按RGB解码本照片，原图(x=100,y=500)的像素实测为(149,130,123)。这是原文件中的一个取样点；不同JPEG解码器可能有细小舍入差异。缩放使用插值，不能假定缩放后的某个像素仍等于它。下面的数值只示范通道换序和归一化。</p>${detailTable(['表达方式','这个像素怎样放置'],[['RGB像素','[149,130,123]'],['同值的BGR排列','[123,130,149]'],['HWC数组定位','image[500,100,:]'],['CHW排列后的定位','R[500,100]、G[500,100]、B[500,100]'],['除以255后的RGB','[0.584314,0.509804,0.482353]'],['方形letterbox的灰边','RGB=(114,114,114) → [0.447059,0.447059,0.447059]']])}<p>灰边也会参与卷积；它不是“被模型自动忽略”的区域。灰边来自图像预处理，第一层卷积自己的padding则默认补0，两者的位置、数值和作用不同。</p>`)
    +detailBlock('13.2 把每一步的shape、dtype、范围写出来',detailTable(['阶段','B=1方形基线的shape','dtype / 数值范围'],[['JPEG解码','[1080,810,3]','uint8 · 0～255'],['等比例缩小后的有效内容','[640,480,3]','uint8 · 插值并取整'],['左右各填充80','[640,640,3]','uint8 · 边缘填114'],['BGR→RGB，HWC→CHW','[3,640,640]','uint8 · 仍是0～255'],['连续内存、转Tensor、加入B','[1,3,640,640]','uint8'],['搬到设备、转float32、除255','[1,3,640,640]','float32 · 0～1']])+`<p>这里按单图推理的顺序说明。训练DataLoader会先为每张图生成CHW Tensor，再由collate_fn沿新的批次轴堆叠；数据内容仍按RGB通道理解。FP16推理可减少部分存储，但不会改变这些shape。</p><p>本图的缩放尺寸刚好是整数；一般图片需要round/ceil和两边整数填充分配，因此应保留原尺寸、实际缩放比例、pad与文件名。不要只凭“输入是640”猜测原图坐标。B=4合批要求四张图的C/H/W一致，targets再用image_index区分每条标注属于哪张。</p>`)
    +detailBlock('13.3 同一条标注的完整变换账本',detailTable(['表示','数值','计算'],[['原图xyxy','(54,405,243,918)','右下角−左上角得到宽高'],['原图xywh','(148.5,661.5,189,513)','中心=(两角坐标之和)/2'],['原图归一化xywh','(0.183333,0.6125,0.233333,0.475)','x/w除810，y/h除1080'],['先缩放，不加pad','xyxy=(32,240,144,544)','每个坐标乘16/27'],['方形输入xyxy','(112,240,224,544)','x两端各加80，y不变'],['方形输入xywh','(168,392,112,304)','再次由两角转中心/宽高'],['方形归一化xywh','(0.2625,0.6125,0.175,0.475)','此时四个值都按输入640归一化'],['合批targets一行','[0,0,0.2625,0.6125,0.175,0.475]','image_index=0，COCO person类别索引=0']])+`<p>坐标有x/y语义，而张量空间轴排列为H/W：本框在原图是x从54到243、y从405到918。它不是先用y索引再用x描述坐标。裁剪、翻转、Mosaic等几何增强发生后，必须重新计算框；旋转后若仍用水平框，通常还要重新取外接矩形并过滤无效框。</p>`);
  }
  function layerDetail(){return detailBlock('14.1 第一层到底怎样算出一个输出数？',`<p>以下固定方形输入。第0层的卷积核权重为[64,3,6,6]：64个输出滤波器，每个同时覆盖3个输入通道、每通道6×6位置。一个输出数是108次乘法累加的结果（不计后续BN/SiLU），不是从照片里取一个像素。该Conv2d没有bias，随后BN有可学习的缩放γ和偏移β。</p><div class="if-equation">z[0,o,oy,ox] = Σc=0..2 Σky=0..5 Σkx=0..5<br>W[o,c,ky,kx] × padded_input[0,c,2oy+ky,2ox+kx]</div><p>换回未补零的输入坐标，窗口左上角是(2ox−2,2oy−2)。切换下面的输出位置，可看窗口覆盖的输入范围；这个范围不是映射回原图后的坐标。</p><label>第一层输出位置<select data-if-patch aria-label="第一层输出位置"><option value="0,0">左上角 (ox,oy)=(0,0)</option><option value="40,100">靠近有效内容 (40,100)</option><option value="100,160">内部位置 (100,160)</option></select></label><div data-if-patch-output class="if-math" aria-live="polite"></div><p>例如oy=0、ox=0时，窗口跨入补零边界；有效输入本身左侧又有letterbox灰边。输入通道3变为64，是64组不同卷积核学习的响应；高宽640变320，是stride=2、kernel=6、padding=2共同决定。</p>`)
    +detailBlock('14.2 权重、特征、梯度分别是什么',detailTable(['对象','形状 / 作用','是否每张图都变化'],[['输入图像','[1,3,640,640]','随图片变化'],['第0层卷积权重','[64,3,6,6]，共6912个卷积权重','推理固定，训练更新'],['第0层BN参数','γ[64]、β[64]，共128个可学习参数','训练更新；运行均值/方差是buffer'],['第0层输出特征','[1,64,320,320]','随输入变化，不是64个类别'],['第0层weight.grad','[64,3,6,6]','反向传播产生，可累积'],['模型保存的权重','参数与必要buffer','不需要为每张推理图单独保存']])+`<p>BN对每个通道利用批次与空间位置上的统计量做归一化，再用γ、β缩放偏移；SiLU(z)=z×sigmoid(z)。Conv→BN→SiLU中的后两步都不改变shape。训练时若只用B=1，BN仍可使用空间样本统计，但不代表小批次训练效果必然稳定。</p><p>第0层输出有64×320×320=6,553,600个数，float32单份约25 MiB，比4.69 MiB的输入还大。分辨率降低不意味着元素总数或显存必然减少；训练还要保存反向传播所需中间量、梯度与优化器状态。不能把所有显示shape的字节相加就当峰值显存。</p>`)
    +detailBlock('14.3 感受野不等于特征图大小或stride',`<p>前两层卷积已能说明区别。输入的采样间隔jump=1、感受野r=1；第0层k=6、s=2后，jump=2、r=6；第1层k=3、s=2后，jump=4、r=6+(3−1)×2=10。递推为jump_out=jump_in×s，r_out=r_in+(k−1)×jump_in（这里dilation=1）。后续的Bottleneck卷积会继续扩展覆盖范围。</p><p>P3的stride=8表示相邻网格对应输入画布约8像素采样间隔，不代表每个网格只看8×8像素。残差和拼接形成多条计算路径，不同路径的覆盖范围也不同；上采样复制特征，并不会重新获得原图中已经丢失的细节。</p>`)
    +detailBlock('14.4 把跨层连接写成有形状的计算式',detailTable(['连接','固定方形B=1的计算式'],[['FPN横向融合1','层11 [1,512,40,40] ⊕ 层6 [1,512,40,40] → 层12 [1,1024,40,40]'],['FPN融合后降通道','层13 C3：1024→512；层14 Conv：512→256'],['FPN横向融合2','层15 [1,256,80,80] ⊕ 层4 [1,256,80,80] → 层16 [1,512,80,80]'],['得到P3','层17 C3 → [1,256,80,80]，一份送Detect，一份继续PAN'],['PAN融合1','层18 [1,256,40,40] ⊕ 层14 [1,256,40,40] → 层19 [1,512,40,40]'],['得到P4','层20 C3 → [1,512,40,40]，一份送Detect，一份继续PAN'],['PAN融合2','层21 [1,512,20,20] ⊕ 层10 [1,512,20,20] → 层22 [1,1024,20,20]'],['得到P5','层23 C3 → [1,1024,20,20]，送Detect']])+`<p>⊕在此表专指通道Concat。来源特征会被保留并被多次读取，不是传给下一层后就必然被丢弃。反向传播时，多条分支对共享上游特征的梯度会累加；因此网络图的前向连接与反向梯度路径都需要考虑。</p>`);
  }
  const anchorGroups=[[[10,13],[16,30],[33,23]],[[30,61],[62,45],[59,119]],[[116,90],[156,198],[373,326]]];
  function trainingDetail(){return detailBlock('15.1 用这个框算一遍anchor匹配，而不是凭直觉选尺度',`<p>本节算例固定B=1、方形640×640、9组随课anchor、无几何增强，且不让AutoAnchor替换模板。假设使用hyp.scratch-low.yaml的anchor_t=4。实际训练可以检查并重估anchor，超参数也能改变；以下“10条分配”只在这些条件下成立，不是YOLOv5对所有物体的固定规则。</p><div class="if-equation">匹配比值 R = max(w/aw, aw/w, h/ah, ah/h)<br>R &lt; anchor_t 才通过（严格小于）</div><p>教学框宽112、高304。先用像素单位比较与anchor宽高，等价于把框和anchor都除以该尺度stride后再比较。它与推理阶段的IoU阈值完全不是同一个判断。</p><label class="if-detail-slider">匹配阈值 anchor_t <output data-if-anchor-value>4.0</output><input type="range" min="2" max="6" value="4" step="0.5" data-if-anchor-threshold aria-label="训练anchor匹配阈值"></label><div data-if-anchor-output aria-live="polite"></div><p>改变阈值只演示分配规则，不会重新训练模型。框的归一化标签和网络的输出形状不会因为这个阈值改变而变化。</p>`)
    +detailBlock('15.2 匹配anchor之后，为什么还有邻格？',`<p>固定阈值4时，P4只有anchor索引2通过，P5三个anchor均通过。每个通过的anchor还要确定网格索引。源码把目标中心转为网格单位gxy，再按与网格边界的关系选择基础格和部分相邻格；使用0.5偏移，最多考察基础格与上下左右，具体筛选由严格条件决定。</p>${detailTable(['尺度','中心gxy','宽高gwh','本例邻格情况'],[['P3 / s8','(21,49)','(14,38)','anchor均失败，不生成本框正样本'],['P4 / s16','(10.5,24.5)','(7,19)','小数部分恰为0.5，不满足<0.5，只有基础格(10,24)'],['P5 / s32','(5.25,12.25)','(3.5,9.5)','基础格(5,12)，左邻(4,12)，上邻(5,11)']])}<svg class="if-neighbor-grid" viewBox="0 0 520 255" role="img" aria-label="P5正样本网格：基础格5,12与左邻4,12、上邻5,11"><rect width="520" height="255" rx="8" fill="#f4f1f8"/><g fill="white" stroke="#d8cee6"><rect x="45" y="25" width="120" height="90"/><rect x="165" y="25" width="120" height="90" fill="#e1f0e9"/><rect x="285" y="25" width="120" height="90"/><rect x="45" y="115" width="120" height="90" fill="#e1f0e9"/><rect x="165" y="115" width="120" height="90" fill="#e9dcf6"/><rect x="285" y="115" width="120" height="90"/></g><g font-size="15" fill="#4f4560" text-anchor="middle"><text x="225" y="66">上邻(5,11)</text><text x="105" y="161">左邻(4,12)</text><text x="225" y="169">基础格(5,12)</text><text x="260" y="239">位置示意：每个通过的P5 anchor均取这3格</text></g><circle cx="195" cy="137.5" r="5" fill="#7750aa"/></svg><p>本例P4共1条分配，P5为3组anchor×3个位置=9条，共10条。基础格的局部中心是(0.25,0.25)，左邻中的目标中心是(1.25,0.25)，上邻是(0.25,1.25)。局部中心大于1并非越界错误；2σ(t)−0.5能覆盖(−0.5,1.5)，就是为了允许这种邻格预测。图用(x,y)标位置，实际索引顺序为[b,a,gj,gi]，即先y再x。</p>`)
    +detailBlock('15.3 从raw里抽出哪几个数来计算损失？',detailTable(['对象','阈值4下本框在P5的形状 / 内容'],[['原始P5预测pi','[1,3,20,20,85]'],['b、a、gj、gi四个索引向量','每个形状[9]，选择本框的9条分配'],['pi[b,a,gj,gi]','[9,85]'],['pxy、pwh','各[9,2]，分别取第0～1与2～3个数'],['objectness logit','每个候选第4个数；整图pi[...,4]为[1,3,20,20]'],['pcls','[9,80]，第5～84个数'],['tbox','[9,4]，局部中心与网格单位宽高'],['tobj','[1,3,20,20]，先置0，再在匹配位置写入定位质量目标']])+`<p>定位使用解码后的正样本框：pxy=2σ(txy)−0.5，pwh=(2σ(twh))²×anchor_grid_units，随后用1−CIoU求均值。CIoU不仅看交并比，还考虑中心距离和长宽比。物体性目标在这份代码中来自CIoU计算结果的detach().clamp(0)，通常口头简称IoU质量目标；detach使这条目标构造支路不再通过该值向定位分支传梯度。</p><p>类别目标形状[9,80]。无标签平滑时，person列为1，其余79列为0；这是多列BCE监督，不是Softmax交叉熵。背景位置没有本框的定位/分类监督，但仍参与物体性损失；其它真值也会产生自己的匹配，不能把本例之外的位置都认定为真实背景。</p>`)
    +detailBlock('再算一个定位损失：零logit候选与真值差在哪里？',`<p>仍用P5的anchor 1=(156,198)、基础格(5,12)，假设四个框logit全为0。Sigmoid(0)=0.5，得到预测中心(176,400)、宽高(156,198)。与真值(168,392,112,304)相比，它偏右下、偏宽、偏矮。以下只是一个正样本的数值例子，不是本照片训练时的实测预测。</p>${detailTable(['计算量','本例数值'],[['预测xyxy','(98,301,254,499)'],['真值xyxy','(112,240,224,544)'],['交集面积','112×198=22,176'],['并集面积','156×198 + 112×304 − 22,176 = 42,760'],['IoU','22,176 / 42,760 ≈ 0.518616'],['中心距离惩罚ρ²/c²','((176−168)²+(400−392)²)/(156²+304²) ≈ 0.001096'],['长宽比项v','(4/π²)×(atan(112/304)−atan(156/198))² ≈ 0.040040'],['α = v/(1−IoU+v)','约0.076789'],['CIoU = IoU−ρ²/c²−αv','约0.514445'],['该正样本的1−CIoU','约0.485555；之后还要跨正样本归约并加权']])}<p>这里c²是同时包住预测与真值的最小外接矩形对角线平方。源码还加很小的eps以稳定除法，表中按普通精度取近似。CIoU可为负，因此代码构造物体性质量目标时会截断到不小于0；本例得到约0.514445。不是把框的损失0.485555直接写成物体性目标，也不是把二者当成同一项损失。</p>`)
    +detailBlock('15.4 三项损失怎样组合，哪些数字会受配置影响？',`<p>关闭Focal包装、标签平滑与自动尺度平衡时，ComputeLoss逐尺度累积定位、物体性和分类项。默认三尺度物体性平衡系数是[4.0,1.0,0.4]；各项再乘hyp中的box/obj/cls增益，最后总和乘批次大小B。train.py还会按检测层数、类别数和输入尺寸调整部分增益，因此不能照抄一个任意配置的权重比例到所有训练。</p><div class="if-equation">Lbox = λbox × Σ尺度 mean正样本(1−CIoU)<br>Lobj = λobj × Σ尺度 balance[i] × BCEWithLogits(pi[...,4], tobj)<br>Lcls = λcls × Σ尺度 BCEWithLogits(pcls, class_targets)<br>返回给反向传播的loss = B × (Lbox + Lobj + Lcls)</div><p>BCE默认做均值归约：分类项在抽出的正样本与类别列上归约，物体性在当前尺度全部网格/anchor上归约。模型里正负项并不是简单按未经归约的元素数直接相加。物体性target为0且logit=0时，单项导数σ(0)−0=+0.5，会推动该logit下降；正类target为1则导数−0.5，推动它上升。</p><p>有正样本的尺度才贡献本例的框和类别项；物体性仍在所有尺度计算。空标签图片可用于学习“不要乱报”，但一个含有未标注真实目标的图片若被当作空标签，会把目标位置错误地监督为背景。本案例只有一条教学标注，不能直接拿去当完整训练集。</p>`)
    +detailBlock('15.5 用一个logit，看清梯度为什么会推动参数改变',`<p>先只看一项普通BCE，目标y=1、logit=z：L=softplus(z)−y×z，∂L/∂z=σ(z)−y。下面忽略pos_weight、均值归约、损失增益、AMP与Focal，仅演示单元素导数。把z往上调，正确正类的概率增加，损失和负梯度幅度会下降。</p><label class="if-detail-slider">正类logit z <output data-if-grad-value>0.0</output><input type="range" min="-4" max="4" step="0.25" value="0" data-if-grad-z aria-label="正类logit梯度演示"></label><div data-if-grad-output class="if-math" aria-live="polite"></div><p>若这个logit来自z=w×f+b，且取示意特征f=2，则∂L/∂w=(σ(z)−1)×2。z=0时导数为−1；用无动量、无衰减的SGD且η=0.01，w会增加0.01。完整模型有大量相互影响的参数和损失项，不能据此保证所有单项损失每一步都下降。</p><p>实际训练中，backward累加梯度，zero_grad清理旧梯度；若刻意进行梯度累积，应在累计到指定步数后再更新并清理。Adam还为参数维护一阶/二阶状态，EMA维护平滑权重副本。一个epoch是遍历一轮训练数据，batch是一次送入的样本组，optimizer step是一次参数更新，它们不是同一个计数。</p>`)
    +detailBlock('15.6 训练结果怎样走向可用的推理权重？',`<p>训练前向需保留计算图供反传，推理使用inference_mode避免这部分开销。每隔若干轮或每轮验证时，模型切到eval，验证集也会解码、筛选并与独立真值比较，统计Precision/Recall和mAP等指标；验证完成再恢复训练模式。训练损失下降不保证验证mAP同步提高，还要检查过拟合、漏标、类别不均衡和数据泄漏。</p><p>可恢复训练的checkpoint可能含epoch、模型、优化器和EMA等状态；供部署的权重可以只保留必要模型内容。选择best权重的标准取决于训练代码的评估与fitness规则，不是“训练集loss最小的那一批”。推理时类别数量、类别名称顺序和模型结构必须与权重匹配。</p>`);
  }
  const nmsBoxes=[{id:'A',box:[112,240,224,544],obj:.9,cls:.8,c:0},{id:'B',box:[116,244,228,548],obj:.85,cls:.8,c:0},{id:'C',box:[112,240,224,544],obj:.8,cls:.75,c:5},{id:'D',box:[350,200,450,400],obj:.8,cls:.7,c:0},{id:'E',box:[112,240,224,544],obj:.5,cls:.4,c:0}];
  const intersectionOverUnion=(a,b)=>{const inter=Math.max(0,Math.min(a[2],b[2])-Math.max(a[0],b[0]))*Math.max(0,Math.min(a[3],b[3])-Math.max(a[1],b[1]));return inter/((a[2]-a[0])*(a[3]-a[1])+(b[2]-b[0])*(b[3]-b[1])-inter);};
  function inferDetail(){return detailBlock('16.1 从85个原始数，手算得到这一个框',`<p>固定方形输入，挑选P5的anchor索引1，模板(156,198)，网格(gx,gy)=(5,12)，stride=32。人为构造下面的logits，让它解码到同一个教学框。其它类别分数在此示例中设得足够低；这不是照片的实际模型输出。</p>${detailTable(['原始分量','人为设定logit','Sigmoid后','解码结果'],[['tx、ty','各−0.510826','各0.375','bx=(0.75−0.5+5)×32=168；by=392'],['tw','−0.307769','约0.423659','bw=(2σ(tw))²×156=112'],['th','0.487626','约0.619547','bh=(2σ(th))²×198=304'],['物体性to','2.197225','0.9','objectness_score=0.9'],['person类别tclass0','1.386294','0.8','组合置信度=0.9×0.8=0.72']])}<p>因此raw[0,1,12,5,:]的前5项可以理解为这些原始参数，person位于组内第5项。解码后前4项变成(168,392,112,304)，再转角点为(112,240,224,544)。源码grid缓存已经包含−0.5；公式若使用整数网格索引，需要显式写出−0.5，不能重复减两次。</p>`)
    +detailBlock('16.2 同一个候选，展平后在第几行？',`<p>Detect的raw排列是[B,anchor,H,W,85]，每个尺度展平顺序为anchor→y→x。P5中anchor=1、y=12、x=5，H=W=20，行号=(1×20+12)×20+5=645（从0开始）。三尺度依P3、P4、P5拼接，P5前已有19200+4800=24000行，因此这个候选在总张量中是第24645行。</p><div class="if-equation">raw_P5[0,1,12,5,k] ↔ decoded[0,24645,k]<br>raw的框参数需要解码，索引对应不代表前4个数值保持不变</div><p>矩形情况下P5的W=15，展平索引和前面候选总数都会变化，所以不能把24645当成这个物体永远的编号。候选行也没有永久对应的“物体身份”；不同输入、不同位置和多个anchor可以对同一个物体产生多个候选。</p>`)
    +detailBlock('16.3 分数筛选到NMS：用五个候选走一遍',`<p>下面五个候选均为人为设定的算例。固定单标签best-class路径：先按物体性预筛，再计算物体性×类别分数并筛选；随后按组合分数降序做贪心NMS。A与B同类、IoU≈0.908；C与A位置相同但类别不同；D在另一位置；E的组合分数较低。C的“bus”只用于展示类别隔离规则，不代表这张照片中该框真的含公交车。</p><div class="if-nms-controls"><label class="if-detail-slider">置信度阈值 <output data-if-conf-value>0.25</output><input type="range" min="0.1" max="0.85" step="0.05" value="0.25" data-if-conf aria-label="候选置信度阈值"></label><label class="if-detail-slider">NMS IoU阈值 <output data-if-iou-value>0.45</output><input type="range" min="0.1" max="0.95" step="0.05" value="0.45" data-if-iou aria-label="NMS重叠阈值"></label><label><input type="checkbox" data-if-agnostic> 类别无关NMS（agnostic）</label></div><div data-if-nms-output aria-live="polite"></div><p>NMS比较的是预测框之间的IoU；训练匹配比较的是框与anchor的比例，验证评估则将预测框与真实标注比较。三种规则的对象和目的不同。默认按类别处理可同时保留重叠但不同类的框；这也意味着NMS本身不能修正错误分类或保证留下真实物体。</p>`)
    +detailBlock('16.4 贪心NMS到底删谁，阈值提高会怎样？',`<ol><li>将当前通过分数筛选的候选按组合置信度从高到低排列。</li><li>保留当前分数最高的框。</li><li>对仍待处理的框，计算与它的IoU；同类且IoU大于阈值的框被抑制，默认类别相关模式下不同类不互相抑制。</li><li>从剩余候选中再取最高分框，重复，直到无候选或达到限制。</li></ol><p>提高置信度阈值通常使进入NMS的框减少；提高IoU阈值使抑制条件更宽松，可能留下更多重复框。“NMS阈值更高”并不是“筛选更严格”。本项目源码还限制进入NMS的候选上限、最终max_det和运行时间；默认非merge路径不把两个框平均合并成新框。</p><p>multi_label=True时，同一候选可按多个超过阈值的类别生成多行；默认best-class路径只取最高类别。分割头还可能带额外mask系数，本课为普通检测，输出每行才是6项，不要把所有YOLO任务都套成相同格式。</p>`)
    +detailBlock('16.5 输出坐标的最后几步也要逐项做完',detailTable(['步骤','教学框的数值'],[['输入画布xywh','(168,392,112,304)'],['中心转两角','x1=168−56=112；y1=392−152=240；x2=224；y2=544'],['去除填充','(112−80,240−0,224−80,544−0)=(32,240,144,544)'],['除以缩放比16/27','(54,405,243,918)'],['裁剪到原图边界','x∈[0,810]、y∈[0,1080]；本框不需要额外裁剪'],['结果一行（示意）','[54,405,243,918,0.72,0]'],['若这张图没有保留框','[0,6]空张量，仍属于批次结果列表的一项']])+`<p>坐标还原只变换前4列，置信度和类别ID不随坐标缩放。若采用拉伸scaleFill，x/y缩放比例可能不同，应按各自比例还原；若输入还有裁剪、旋转或其它变换，则需要完整的逆变换，不能只做一个减pad再除r。批次内每张图必须使用自己的原尺寸和预处理记录。</p>`);
  }
  function detail(root){return `<div class="if-deep"><h3>继续拆开中间步骤</h3><p class="if-note">以下手算固定640×640方形、B=1的基线；上方画布/批次选择用于对照。所有人为构造的预测、梯度与候选示例均有说明。</p>${root.dataset.ifKind==='pre'?preDetail():root.dataset.ifKind==='layers'?layerDetail():root.dataset.ifKind==='train'?trainingDetail():inferDetail()}</div>`;}
  function refreshDetail(root){
    const patch=root.querySelector('[data-if-patch]');if(patch){const [x,y]=patch.value.split(',').map(Number);let cells='';for(let ky=0;ky<6;ky++)for(let kx=0;kx<6;kx++){const ix=2*x-2+kx,iy=2*y-2+ky,zero=ix<0||iy<0||ix>639||iy>639,gray=ix<80||ix>=560;cells+=`<rect x="${kx*45+20}" y="${ky*38+15}" width="43" height="36" fill="${zero?'#d7d6dc':gray?'#e6e6e6':'#e5d5f4'}"/><text x="${kx*45+41.5}" y="${ky*38+38}" text-anchor="middle" font-size="11" fill="#51435d">${zero?'0':gray?'0.447':'图像'}</text>`;}root.querySelector('[data-if-patch-output]').innerHTML=`<p>输出[0,o,${y},${x}]：输入x覆盖${2*x-2}～${2*x+3}，y覆盖${2*y-2}～${2*y+3}，同时覆盖3通道。每个输出通道使用一套3×6×6权重；o=0～63。</p><svg class="if-patch-grid" viewBox="0 0 310 265" role="img" aria-label="一个输入通道的6乘6采样窗口，区分卷积补零、letterbox灰边与图像内容">${cells}<text x="155" y="257" text-anchor="middle" font-size="11" fill="#51435d">一个通道的窗口：0补零 / 0.447灰边 / 图像值</text></svg><p>“图像”只标示来自有效图像内容的位置，未展示实际缩放像素或卷积结果。其它两个通道也在相同坐标采样。</p>`;}
    const anchor=root.querySelector('[data-if-anchor-threshold]');if(anchor){const threshold=Number(anchor.value);root.querySelector('[data-if-anchor-value]').textContent=threshold.toFixed(1);const counts=[0,0,0],rows=anchorGroups.flatMap((group,i)=>group.map(([aw,ah],a)=>{const ratio=Math.max(112/aw,aw/112,304/ah,ah/304),pass=ratio<threshold;if(pass)counts[i]++;return ['P'+(i+3)+' / anchor '+a,aw+'×'+ah,ratio.toFixed(3),pass?'通过':'不通过'];}));root.querySelector('[data-if-anchor-output]').innerHTML=detailTable(['尺度 / 索引','anchor像素宽高','最大比例R','R < '+threshold],rows)+`<div class="if-math">通过anchor数：P3=${counts[0]}，P4=${counts[1]}，P5=${counts[2]}<br>当前阈值范围内P3均不通过。加上本框的邻格规则：P4的${counts[1]}×1 + P5的${counts[2]}×3 = ${counts[1]+counts[2]*3} 条正样本分配</div>`;}
    const grad=root.querySelector('[data-if-grad-z]');if(grad){const z=Number(grad.value),p=1/(1+Math.exp(-z));root.querySelector('[data-if-grad-value]').textContent=z.toFixed(2);root.querySelector('[data-if-grad-output]').innerHTML=`σ(z)=${p.toFixed(4)}；y=1<br>单元素BCE=${Math.log1p(Math.exp(-z)).toFixed(4)}<br>∂L/∂z=σ(z)−1=${(p-1).toFixed(4)}<br>若f=2：∂L/∂w=${(2*(p-1)).toFixed(4)}；简化SGD更新量Δw=${(-.01*2*(p-1)).toFixed(5)}`;}
    const conf=root.querySelector('[data-if-conf]');if(conf){const ct=Number(conf.value),it=Number(root.querySelector('[data-if-iou]').value),agnostic=root.querySelector('[data-if-agnostic]').checked;root.querySelector('[data-if-conf-value]').textContent=ct.toFixed(2);root.querySelector('[data-if-iou-value]').textContent=it.toFixed(2);const kept=[],statuses={};nmsBoxes.forEach(n=>{if(n.obj<=ct||Number((n.obj*n.cls).toFixed(8))<=ct)statuses[n.id]='分数筛除';});nmsBoxes.filter(n=>!statuses[n.id]).sort((a,b)=>b.obj*b.cls-a.obj*a.cls).forEach(n=>{const suppressor=kept.find(k=>(agnostic||k.c===n.c)&&intersectionOverUnion(k.box,n.box)>it);if(suppressor)statuses[n.id]='被'+suppressor.id+'抑制 · IoU='+intersectionOverUnion(suppressor.box,n.box).toFixed(3);else{kept.push(n);statuses[n.id]='保留';}});const canvas=(items,all)=>`<svg viewBox="0 0 640 640" role="img" aria-label="${all?'五个人工候选框示意':'筛选和NMS后保留的人工候选框'}"><rect width="640" height="640" fill="#727272"/><image href="${photo}" x="80" width="480" height="640"/>${items.map(n=>{const [x1,y1,x2,y2]=n.box,color={A:'#3ff2b1',B:'#ffd257',C:'#bc94ff',D:'#68ddff',E:'#ff9f9f'}[n.id];return `<rect x="${x1}" y="${y1}" width="${x2-x1}" height="${y2-y1}" fill="none" stroke="${color}" stroke-width="4"/><text x="${x1+5}" y="${y1+20+20*nmsBoxes.indexOf(n)}" fill="${color}" stroke="#26303b" stroke-width=".5" font-size="20">${n.id} ${(n.obj*n.cls).toFixed(2)}</text>`;}).join('')}</svg>`;root.querySelector('[data-if-nms-output]').innerHTML=`<div class="if-photo-pair"><figure>${canvas(nmsBoxes,true)}<figcaption>五个手工候选 · 分数筛选前</figcaption></figure><b aria-hidden="true">→</b><figure>${canvas(kept,false)}<figcaption>当前筛选与NMS后的保留框</figcaption></figure></div>`+detailTable(['候选','类别','xyxy','obj×class','本次结果'],nmsBoxes.map(n=>[n.id,n.c===0?'person(0)':'bus(5)',n.box.join(','),(n.obj*n.cls).toFixed(2),statuses[n.id]]))+`<div class="if-math">最终保留：${kept.map(n=>n.id).join('、')||'无'}；结果形状[${kept.length},6]<br>这些候选、类别与分数均为规则演示，不是模型预测。</div>`;}
  }
  const body=(root)=>{let basic=root.dataset.ifKind==='pre'?preprocess():root.dataset.ifKind==='layers'?layers(root):root.dataset.ifKind==='train'?training(root):inference(root);if(root.dataset.ifKind==='layers')basic+=moduleGraphic(entries[Number(root.dataset.layer||0)]);return basic+detail(root);};
  function render(kind){return `<section class="if-workbench" data-if-root data-if-kind="${kind}" data-layer="0" data-step="0"><span class="if-kicker">ONE PHOTO, ALL THE WAY · 一张照片贯穿全程</span>${kind==='train'?'':settings()}<div data-if-content></div></section>`;}
  function update(root){
    const fields=['data-if-patch','data-if-anchor-threshold','data-if-grad-z','data-if-conf','data-if-iou','data-if-agnostic'];
    const saved=fields.map(attr=>{const el=root.querySelector('['+attr+']');return el?{attr,value:el.value,checked:el.checked}:null;}).filter(Boolean);
    root.querySelector('[data-if-content]').innerHTML=body(root);
    saved.forEach(({attr,value,checked})=>{const el=root.querySelector('['+attr+']');if(el){el.value=value;if(el.type==='checkbox')el.checked=checked;}});
    refreshDetail(root);
  }
  function updateAll(){document.querySelectorAll('[data-if-root]').forEach(root=>{const layout=root.querySelector('[data-if-layout]'),batch=root.querySelector('[data-if-batch]');if(layout)layout.value=choice.rect?'rect':'square';if(batch)batch.value=String(choice.b);update(root);});}
  const previous=window.lessonPlaygrounds||{};
  window.lessonPlaygrounds={render(id,i){return (previous.render?.(id,i)||'')+(id==='architecture'&&i>=12&&i<=15?render(['pre','layers','train','infer'][i-12]):'');},initialize(){previous.initialize?.();updateAll();}};
  document.addEventListener('change',event=>{if(event.target.matches('[data-if-patch],[data-if-agnostic]')){refreshDetail(event.target.closest('[data-if-root]'));return;}if(event.target.matches('[data-if-layout]'))choice.rect=event.target.value==='rect';else if(event.target.matches('[data-if-batch]'))choice.b=Number(event.target.value);else return;updateAll();});
  document.addEventListener('input',event=>{if(event.target.matches('[data-if-anchor-threshold],[data-if-grad-z],[data-if-conf],[data-if-iou]'))refreshDetail(event.target.closest('[data-if-root]'));});
  document.addEventListener('click',event=>{const b=event.target.closest('button'),root=b?.closest('[data-if-root]');if(!root)return;if(b.dataset.ifLayer!==undefined)root.dataset.layer=b.dataset.ifLayer;else if(b.dataset.ifTrainStep!==undefined)root.dataset.step=b.dataset.ifTrainStep;else if(b.dataset.ifInferStep!==undefined)root.dataset.step=b.dataset.ifInferStep;else return;update(root);});
})();
